const body=$json.body??$json;
const lead=body.lead??body;
const rules={budget:Number(body.rules?.budget??2),urgency:Number(body.rules?.urgency??2),fit:Number(body.rules?.fit??2)};
const budget=Math.max(0,Math.min(5,Number(lead.budgetScore??0)));
const urgency=Math.max(0,Math.min(5,Number(lead.urgencyScore??0)));
const fit=Math.max(0,Math.min(5,Number(lead.fitScore??0)));
const score=budget*rules.budget+urgency*rules.urgency+fit*rules.fit;
const threshold=Math.max(1,Number(body.threshold??18));
return [{json:{leadId:lead.id??null,score,threshold,qualified:score>=threshold,humanApprovalRequired:true,automatedOutreach:false,components:{budget,urgency,fit},lead}}];
